// Splits the node_modules file list of listNodeModules.ts into parts that take about as long to extract,
// which cache.sh and cache.ps1 archive and extract in parallel. Writes `<list file>.<index>` for each
// non-empty part. Each part is a contiguous range of the list, so that most folders are in one part.

import fs from 'fs';

const [listFile, partsArgument] = process.argv.slice(2);
const parts = Number(partsArgument);
if (!listFile || !Number.isInteger(parts) || parts < 1) {
	console.error('Usage: node splitList.ts <list file> <parts>');
	process.exit(1);
}

const files = fs.readFileSync(listFile, 'utf8').split('\n').filter(Boolean);
// Creating a file costs about as much time as extracting 16 KB of it.
const weights = files.map(file => {
	try {
		const stat = fs.lstatSync(file);
		return (stat.isFile() ? stat.size : 0) + 16 * 1024;
	} catch {
		return 16 * 1024;
	}
});
const partWeight = weights.reduce((a, b) => a + b, 0) / parts;

const lists: string[][] = Array.from({ length: parts }, () => []);
let accumulated = 0;
files.forEach((file, index) => {
	lists[Math.min(parts - 1, Math.floor(accumulated / partWeight))].push(file);
	accumulated += weights[index];
});
lists.filter(list => list.length > 0).forEach((list, index) => fs.writeFileSync(`${listFile}.${index}`, list.join('\n') + '\n'));
